def transform(grid):
    h, w = len(grid), len(grid[0])

    # Find the uniform divider.
    for r in range(h):
        if len(set(grid[r])) == 1:
            panel_a, panel_b = grid[:r], grid[r + 1:]
            break
    else:
        for c in range(w):
            if len({grid[r][c] for r in range(h)}) == 1:
                panel_a = [row[:c] for row in grid]
                panel_b = [row[c + 1:] for row in grid]
                break
        else:
            panel_a, panel_b = grid, []

    # The panel with the denser minority-color pattern is the one to output.
    def minority_density(panel):
        from collections import Counter
        vals = [v for row in panel for v in row]
        counts = Counter(vals)
        return (len(vals) - max(counts.values())) / len(vals)

    panel = max((p for p in (panel_a, panel_b) if p and p[0]),
                key=minority_density)
    from collections import Counter
    bg = Counter(v for row in panel for v in row).most_common(1)[0][0]
    return [[1 if v == bg else 3 for v in row] for row in panel]
